<?php require_once App\Core\Config::$DIR_BASE . '/App/Views/SBAdmin/Contract/ContractViewHelpers.php'; $readonly = (($data['FormData']['Status'] ?? 'Draft') !== 'Draft'); ?>
<form method="post" action="/Contract/Contract/Show/<?= rawurlencode($data['ContractId']); ?>"><input type="hidden" name="RepositoryId" value="<?= ctr_e(App\Core\AuthSession::get()['RPS_ID'] ?? ''); ?>"><fieldset <?= $readonly ? 'disabled' : ''; ?>><div class="form-row"><div class="form-group col-md-4"><label>Usuário</label><input class="form-control" name="UserId" maxlength="65" required value="<?= ctr_e($data['FormData']['UserId']); ?>"></div><div class="form-group col-md-4"><label>Cliente</label><input class="form-control" name="Client" maxlength="255" placeholder="CNPJ, e-mail ou nome" value="<?= ctr_e($data['FormData']['Client'] ?? ''); ?>"></div><div class="form-group col-md-4"><label>Grupo de concorrência</label><select class="form-control" name="ConcurrencyGroupId" required><option value="">Selecione</option><?php foreach ($data['Groups'] as $group): ?><option value="<?= (int) $group['Id']; ?>" <?= ((string) $data['FormData']['ConcurrencyGroupId'] === (string) $group['Id']) ? 'selected' : ''; ?>><?= ctr_e($group['Name']); ?></option><?php endforeach; ?></select></div></div><div class="form-row"><div class="form-group col-md-4"><label>Ciclo de cobrança</label><select class="form-control" name="BillingCycle"><option value="">Não informado</option><?php foreach (['Monthly' => 'Mensal', 'Quarterly' => 'Trimestral', 'Annual' => 'Anual', 'OneTime' => 'Único'] as $value => $label): ?><option value="<?= $value; ?>" <?= (($data['FormData']['BillingCycle'] ?? '') === $value) ? 'selected' : ''; ?>><?= $label; ?></option><?php endforeach; ?></select></div><div class="form-group col-md-4"><label>Início</label><input class="form-control" type="datetime-local" name="StartDate" value="<?= ctr_e(str_replace(' ', 'T', substr((string) ($data['FormData']['StartDate'] ?? ''), 0, 16))); ?>"></div><div class="form-group col-md-4"><label>Término</label><input class="form-control" type="datetime-local" name="EndDate" value="<?= ctr_e(str_replace(' ', 'T', substr((string) ($data['FormData']['EndDate'] ?? ''), 0, 16))); ?>"></div></div><div class="form-row"><div class="form-group col-md-4"><label>Contrato anterior</label><input class="form-control" name="ParentContractId" maxlength="36" value="<?= ctr_e($data['FormData']['ParentContractId']); ?>"></div><div class="form-group col-md-8"><label>Descrição do contrato</label><input class="form-control" name="Description" maxlength="255" value="<?= ctr_e($data['FormData']['Description'] ?? ''); ?>"></div></div><div class="form-group"><label>Hash do contrato</label><input class="form-control" name="ContractHash" maxlength="256" value="<?= ctr_e($data['FormData']['ContractHash']); ?>"></div><hr><div class="form-group"><label>Template</label><input class="form-control" name="TemplatePath" maxlength="255" value="<?= ctr_e($data['FormData']['TemplatePath']); ?>"></div><div class="form-group"><label>Termos personalizados</label><textarea class="form-control" name="CustomTerms" rows="4"><?= ctr_e($data['FormData']['CustomTerms']); ?></textarea></div><div class="form-group"><label>Conteúdo da minuta</label><textarea class="form-control" name="TemplateContent" rows="8"><?= ctr_e($data['FormData']['TemplateContent']); ?></textarea></div></fieldset>
<?php if (!$readonly): ?><button class="btn btn-primary" name="btnSaveDraft">Salvar rascunho</button><?php endif; ?>
<?php if ($data['ContractId'] !== ''): ?><a class="btn btn-outline-secondary" href="/Contract/Contract/Detail/<?= rawurlencode($data['ContractId']); ?>">Detalhe</a><a class="btn btn-outline-secondary" href="/Contract/ContractItem/Index/<?= rawurlencode($data['ContractId']); ?>">Itens</a><a class="btn btn-outline-secondary" href="/Contract/ContractSignatory/Index/<?= rawurlencode($data['ContractId']); ?>">Signatários</a><?php if (($data['FormData']['Status'] ?? '') === 'Draft'): ?><button class="btn btn-success" name="btnActivate">Ativar</button><?php endif; ?><?php if (in_array(($data['FormData']['Status'] ?? ''), ['Draft', 'Active'], true)): ?><button class="btn btn-danger" name="btnCancel">Cancelar</button><button class="btn btn-warning" name="btnExpire">Expirar</button><?php endif; ?><?php endif; ?></form>
